    sortOrder: index,
    targetRelativePath,
    sourceRelativePath: entry.sourceRelativePath == null ? null : normalizeRelativePath(entry.sourceRelativePath, 'selectedFiles[' + index + '].sourceRelativePath'),
    absolutePath: stablePath,
  };
