if (seenTargets.size !== stableByRelativePath.size) {
  const extra = [...stableByRelativePath.keys()].filter((relativePath) => !seenTargets.has(relativePath));
  throw new Error('来源目录中的图片与 manifest 不一致，未登记图片：' + extra.join(', '));
