const maxImageCount = boundedInteger(params.maxImageCount, 'maxImageCount', 1, 100);
if (minImageCount > maxImageCount) throw new Error('minImageCount 不得大于 maxImageCount。');
if (selectedImages.length < minImageCount) throw new Error('子目录中没有足够图片：至少需要 ' + minImageCount + ' 张，当前 ' + selectedImages.length + ' 张。');
if (selectedImages.length > maxImageCount) throw new Error('图片数量超过上限：最多允许 ' + maxImageCount + ' 张，当前 ' + selectedImages.length + ' 张。');

const sourceChildName = cleanName(packageInput.sourceChildName, 'product');
const SKU = String(params.SKU || '').trim();
const productName = String(params.productName || '').trim();
const variants = String(params.variants || '').trim();
const executionId = String($execution.id || '').trim();
if (!/^\d{7}$/.test(SKU)) throw new Error('n8n_setParameter_xxx.json 的 SKU 必须是保留前导零的 7 位数字。');
if (!productName) throw new Error('n8n_setParameter_xxx.json 的 productName 不能为空。');
if (!variants) throw new Error('n8n_setParameter_xxx.json 的 variants 不能为空。');
if (!/^\d+$/.test(executionId)) throw new Error('当前工作流 executionId 无效。');
const outputParentDir = normalizeUserPath(params.outputParentDir || '');
const outputSubDir = outputParentDir + '/' + SKU + '-' + cleanName(productName, 'product') + '-' + executionId;
const outputVideoPath = outputSubDir + '/' + sourceChildName + '.mp4';
const jobJsonPath = outputSubDir + '/job.json';

const job = {
  sourceChildDir,
  sourceChildName,
  SKU,
  productName,
  variants,
  n8nExecutionId: executionId,
  readySubmissionId: packageInput.readySubmissionId,
  parameterFileName: packageInput.parameterFileName,
  e004RenderLockPath: packageInput.e004RenderLockPath,
  sourcePackageSha256: packageInput.folderStableContentSha256,
  imagePaths: selectedImages,
  imageCount: selectedImages.length,
  skippedImageCount: 0,
  imageOrderSource: ordered.orderSource,
  orderedSelection: orderedSelection.map(({ absolutePath, ...entry }) => entry),
  selectionManifestPath: normalizeUserPath(manifestPath),
  outputSubDir,
  outputVideoPath,
  effectPreset: params.effectPreset || 'case1',
  createdAt: new Date().toISOString(),
  params,
};

return [{ json: { ...job, job, jobJsonPath, renderWorkflowId: 'x8D4EHfqI2DHcgL7' } }];

const fs = require('fs');
const path = require('path');
const source = $('Collect Image Files').first().json || {};
const job = source.job || {};

function normalizeForCompare(value) {
  const resolved = path.resolve(String(value || ''));
  return path.sep === '\\' ? resolved.toLowerCase() : resolved;
}

function isInside(root, target) {
  const relative = path.relative(root, target);
  return relative === '' || (relative !== '..' && !relative.startsWith('..' + path.sep) && !path.isAbsolute(relative));
}

function atomicWriteJson(target, value) {
  if (fs.existsSync(target)) throw new Error('E004_OUTPUT_METADATA_ALREADY_EXISTS: ' + target);
  const temporary = target + '.tmp-' + String($execution.id || Date.now());
  let completed = false;
  try {
    fs.writeFileSync(temporary, JSON.stringify(value, null, 2) + '\n', { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    fs.renameSync(temporary, target);
    completed = true;
  } finally {
    if (!completed && fs.existsSync(temporary)) fs.rmSync(temporary, { force: true });
  }
}

if (typeof job.SKU !== 'string' || !/^\d{7}$/.test(job.SKU.trim())) throw new Error('job.SKU 必须是 7 位 String。');
if (typeof job.productName !== 'string' || !job.productName.trim()) throw new Error('job.productName 必须是非空 String。');
if (typeof job.variants !== 'string' || !job.variants.trim()) throw new Error('job.variants 必须是非空 String。');
if (!Array.isArray(job.imagePaths) || job.imagePaths.length !== Number(job.imageCount || 0)) throw new Error('job.imagePaths 与 imageCount 不一致。');

const outputParentDir = path.resolve(String(job.params?.outputParentDir || ''));
const outputSubDir = path.resolve(String(job.outputSubDir || ''));
if (!outputParentDir || !outputSubDir || !isInside(outputParentDir, outputSubDir) || normalizeForCompare(outputParentDir) === normalizeForCompare(outputSubDir)) {
  throw new Error('Unsafe outputSubDir outside outputParentDir: ' + outputSubDir);
}
if (!fs.existsSync(outputParentDir) || !fs.lstatSync(outputParentDir).isDirectory() || fs.lstatSync(outputParentDir).isSymbolicLink()) {
  throw new Error('outputParentDir must be an existing real directory: ' + outputParentDir);
}
const parentReal = fs.realpathSync(outputParentDir);
if (!isInside(parentReal, fs.realpathSync(outputParentDir))) throw new Error('outputParentDir realpath validation failed.');

const expectedJobPath = path.resolve(outputSubDir, 'job.json');
const requestedJobPath = path.resolve(String(source.jobJsonPath || ''));
if (normalizeForCompare(expectedJobPath) !== normalizeForCompare(requestedJobPath)) throw new Error('jobJsonPath must be outputSubDir/job.json');

const renderJob = {
  ...job,
  schemaVersion: 2,
  workflowCode: 'E004',
  status: 'RENDERING',
  renderStartedAt: new Date().toISOString(),
  sourcePackageSha256: String(source.folderStableContentSha256 || ''),
};
const taskContext = {
  schemaVersion: 2,
  workflowCode: 'E004',
  status: 'RENDERING',
  SKU: job.SKU.trim(),
  productName: job.productName.trim(),
  variants: job.variants.trim(),
  ...(job.variantId ? { variantId: String(job.variantId) } : {}),
  ...(job.readySubmissionId ? { sourceSubmissionId: String(job.readySubmissionId) } : {}),
  n8nExecutionId: String(job.n8nExecutionId || $execution.id || ''),
  renderStartedAt: renderJob.renderStartedAt,
};

fs.mkdirSync(outputSubDir, { recursive: false });
if (fs.lstatSync(outputSubDir).isSymbolicLink() || !fs.lstatSync(outputSubDir).isDirectory()) throw new Error('outputSubDir must be a real directory.');
if (!isInside(parentReal, fs.realpathSync(outputSubDir))) throw new Error('outputSubDir realpath escaped outputParentDir.');
const taskContextPath = path.resolve(outputSubDir, 'task-context.json');
atomicWriteJson(expectedJobPath, renderJob);
atomicWriteJson(taskContextPath, taskContext);

const parsedJob = JSON.parse(fs.readFileSync(expectedJobPath, 'utf8'));
const parsedContext = JSON.parse(fs.readFileSync(taskContextPath, 'utf8'));
if (parsedJob.status !== 'RENDERING' || parsedJob.imagePaths.length !== Number(job.imageCount)) throw new Error('job.json verification failed.');
if (parsedContext.status !== 'RENDERING' || parsedContext.variants !== taskContext.variants) throw new Error('task-context.json verification failed.');

return [{ json: {
  ...source,
  job: renderJob,
  taskContextPath: taskContextPath.replace(/\\/g, '/'),
  jobJsonWritten: true,
  jobJsonPath: expectedJobPath.replace(/\\/g, '/'),
  jobJsonSizeBytes: fs.statSync(expectedJobPath).size,
  jobJsonImageCount: parsedJob.imagePaths.length,
} }];

const fs = require('fs');
const path = require('path');
const render = $input.first().json || {};
const job = $('Collect Image Files').first().json || {};
const packageState = $('Parse Stable Result').first().json || {};

if (render.success !== true || render.ok !== true) {
  throw new Error('E004_RENDER_RESULT_INVALID: success=' + String(render.success) + ', ok=' + String(render.ok));
}
if (!job.readySubmissionId) throw new Error('E004_RENDER_RESULT_MISSING_SUBMISSION_ID');
if (!render.outputVideoPath || Number(render.sizeBytes || 0) <= 0) throw new Error('E004_RENDER_OUTPUT_INVALID');

function atomicWriteJson(target, value) {
  const temporary = target + '.tmp-' + String($execution.id || Date.now());
  let completed = false;
  try {
    fs.writeFileSync(temporary, JSON.stringify(value, null, 2) + '\n', { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    fs.renameSync(temporary, target);
    completed = true;
  } finally {
    if (!completed && fs.existsSync(temporary)) fs.rmSync(temporary, { force: true });
  }
}

const outputSubDir = path.resolve(String(job.outputSubDir || ''));
const outputVideoPath = path.resolve(String(render.outputVideoPath || ''));
const relativeOutput = path.relative(outputSubDir, outputVideoPath);
if (!relativeOutput || relativeOutput === '..' || relativeOutput.startsWith('..' + path.sep) || path.isAbsolute(relativeOutput)) {
  throw new Error('E004_RENDER_OUTPUT_OUTSIDE_DIRECTORY');
}
const completedAt = new Date().toISOString();
const completionPath = path.join(outputSubDir, '_COMPLETE.json');
atomicWriteJson(completionPath, {
  schemaVersion: 1,
  workflowCode: 'E004',
  status: 'COMPLETED',
  submissionId: job.readySubmissionId,
  n8nExecutionId: String(job.n8nExecutionId || $execution.id || ''),
  completedAt,
  outputVideoPath: outputVideoPath.replace(/\\/g, '/'),
  sizeBytes: Number(render.sizeBytes),
  durationSeconds: Number(render.durationSeconds || 0),
  mediaProbe: render.mediaProbe || null,
});

const state = $getWorkflowStaticData('global');
if (!state.e004CompletedSubmissions || typeof state.e004CompletedSubmissions !== 'object' || Array.isArray(state.e004CompletedSubmissions)) state.e004CompletedSubmissions = {};
const now = Date.now();
const keepMs = 30 * 24 * 60 * 60 * 1000;
for (const [key, completedTimestamp] of Object.entries(state.e004CompletedSubmissions)) {
  if (!Number.isFinite(Number(completedTimestamp)) || now - Number(completedTimestamp) > keepMs) delete state.e004CompletedSubmissions[key];
}
state.e004CompletedSubmissions[job.readySubmissionId] = now;

const lockPath = path.resolve(String(packageState.e004RenderLockPath || ''));
const sourceRoot = path.resolve(String(job.sourceChildDir || ''));
if (lockPath && path.dirname(lockPath) === sourceRoot && path.basename(lockPath) === '._E004_RENDER.lock') {
  fs.rmSync(lockPath, { force: true });
}

return [{ json: {
  success: true,
  submissionId: job.readySubmissionId,
  parameterFileName: job.parameterFileName || '',
  sourceChildDir: job.sourceChildDir,
  sourceChildName: job.sourceChildName,
  imageCount: job.imageCount,
  effectPreset: job.effectPreset,
  outputSubDir: job.outputSubDir,
  outputVideoPath: render.outputVideoPath,
  outputSizeBytes: Number(render.sizeBytes),
  durationSeconds: Number(render.durationSeconds || job.params?.targetDuration || 0),
  completionFile: completionPath.replace(/\\/g, '/'),
  completedAt,
  render,
} }];
